/**
 * @suppress
 */
public object FfiConverterTypeGroupDevice: FfiConverter<GroupDevice, Long> {
    override fun lower(value: GroupDevice): Long {
        return value.uniffiCloneHandle()
    }

    override fun lift(value: Long): GroupDevice {
        return GroupDevice(UniffiWithHandle, value)
    }

    override fun read(buf: ByteBuffer): GroupDevice {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: GroupDevice) = 8UL

    override fun write(value: GroupDevice, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}



