/**
 * Every failure, with a stable machine code (see `docs/group-e2ee.md`).
 */
sealed class GroupCryptoException: kotlin.Exception() {
    
    /**
     * Operation failed; `code` is stable, `message` is for logs.
     */
    class Failure(
        
        /**
         * Stable code such as `stale_epoch` or `pending_commit`.
         */
        val `code`: kotlin.String, 
        
        /**
         * Human-readable detail (never contains secrets).
         */
        val `detail`: kotlin.String
        ) : GroupCryptoException() {
        override val message
            get() = "code=${ `code` }, detail=${ `detail` }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<GroupCryptoException> {
        override fun lift(error_buf: RustBuffer.ByValue): GroupCryptoException = FfiConverterTypeGroupCryptoError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeGroupCryptoError : FfiConverterRustBuffer<GroupCryptoException> {
    override fun read(buf: ByteBuffer): GroupCryptoException {
        

        return when(buf.getInt()) {
            1 -> GroupCryptoException.Failure(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: GroupCryptoException): ULong {
        return when(value) {
            is GroupCryptoException.Failure -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`code`)
                + FfiConverterString.allocationSize(value.`detail`)
            )
        }
    }

    override fun write(value: GroupCryptoException, buf: ByteBuffer) {
        when(value) {
            is GroupCryptoException.Failure -> {
                buf.putInt(1)
                FfiConverterString.write(value.`code`, buf)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



/**
 * Result of processing one incoming message.
 */
sealed class Incoming {
    
    data class Message(
        val `message`: dev.pigeonpost.groupcrypto.ReceivedMessage) : Incoming()
        
    {
        

        companion object
    }
    
    data class HistoryOffer(
        val `offer`: dev.pigeonpost.groupcrypto.HistoryOffer) : Incoming()
        
    {
        

        companion object
    }
    
    data class Commit(
        val `outcome`: dev.pigeonpost.groupcrypto.CommitOutcome) : Incoming()
        
    {
        

        companion object
    }
    
    data class OwnCommitConfirmed(
        val `outcome`: dev.pigeonpost.groupcrypto.CommitOutcome) : Incoming()
        
    {
        

        companion object
    }
    
    object Own : Incoming()
    
    

    

    
    


    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeIncoming : FfiConverterRustBuffer<Incoming>{
    override fun read(buf: ByteBuffer): Incoming {
        return when(buf.getInt()) {
            1 -> Incoming.Message(
                FfiConverterTypeReceivedMessage.read(buf),
                )
            2 -> Incoming.HistoryOffer(
                FfiConverterTypeHistoryOffer.read(buf),
                )
            3 -> Incoming.Commit(
                FfiConverterTypeCommitOutcome.read(buf),
                )
            4 -> Incoming.OwnCommitConfirmed(
                FfiConverterTypeCommitOutcome.read(buf),
                )
            5 -> Incoming.Own
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: Incoming) = when(value) {
        is Incoming.Message -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypeReceivedMessage.allocationSize(value.`message`)
            )
        }
        is Incoming.HistoryOffer -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypeHistoryOffer.allocationSize(value.`offer`)
            )
        }
        is Incoming.Commit -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypeCommitOutcome.allocationSize(value.`outcome`)
            )
        }
        is Incoming.OwnCommitConfirmed -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypeCommitOutcome.allocationSize(value.`outcome`)
            )
        }
        is Incoming.Own -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
    }

    override fun write(value: Incoming, buf: ByteBuffer) {
        when(value) {
            is Incoming.Message -> {
                buf.putInt(1)
                FfiConverterTypeReceivedMessage.write(value.`message`, buf)
                Unit
            }
            is Incoming.HistoryOffer -> {
                buf.putInt(2)
                FfiConverterTypeHistoryOffer.write(value.`offer`, buf)
                Unit
            }
            is Incoming.Commit -> {
                buf.putInt(3)
                FfiConverterTypeCommitOutcome.write(value.`outcome`, buf)
                Unit
            }
            is Incoming.OwnCommitConfirmed -> {
                buf.putInt(4)
                FfiConverterTypeCommitOutcome.write(value.`outcome`, buf)
                Unit
            }
            is Incoming.Own -> {
                buf.putInt(5)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}






/**
